STATE_KEY = "opensheet.workbooks.v1"

PROFILE_DIRS = (
    "/home/user/.config/google-chrome/Default/Local Storage/leveldb",
    "/home/user/.config/chromium/Default/Local Storage/leveldb",
)


def _directories(params: Mapping[str, Any]) -> list[str]:
    extra = (
        params.get("profile_dirs")
        or params.get("local_state_paths")
        or params.get("storage_dirs")
    )
    found: list[str] = []
    if isinstance(extra, (list, tuple)):
        for item in extra:
            text = str(item or "").strip()
            if text and text not in found:
                found.append(text)
    for item in PROFILE_DIRS:
        if item not in found:
            found.append(item)
    return found


def _run_python(controller: Any, program: str, timeout: int = 60) -> Any:
    if controller is not None and hasattr(controller, "run_python_script"):
        try:
            payload = controller.run_python_script(program, timeout=timeout)
        except Exception:
            payload = None
        if isinstance(payload, Mapping):
            text = str(payload.get("stdout") or payload.get("output") or "").strip()
            if text:
                try:
                    return json.loads(text)
                except ValueError:
                    return None
    return None


def _read_one(controller: Any, directory: str, key: str) -> Any:
    program = (
        LOCAL_STORAGE_SOURCE
        + "\nprint(json.dumps(read_state(%s, %s), ensure_ascii=False))\n"
        % (json.dumps(directory), json.dumps(key))
    )
    parsed = _run_python(controller, program, timeout=60)
    if parsed is not None:
        return parsed
    try:
        from evaluators.cua_review.platforms.linux.local_storage import read_state

        return read_state(directory, key)
    except Exception:
        return None


def _read_document(controller: Any, key: str, directories: list[str]) -> tuple[Any, str]:
    for directory in directories:
        value = _read_one(controller, directory, key)
        if value is not None:
            return value, directory
    return None, ""


def _cell(sheet: Mapping[str, Any], address: str) -> dict[str, Any]:
    cells = sheet.get("cells") if isinstance(sheet.get("cells"), Mapping) else {}
    value = cells.get(address)
    return dict(value) if isinstance(value, Mapping) else {}


def _cell_value(cell: Mapping[str, Any]) -> str:
    value = cell.get("value")
    return "" if value is None else str(value)


def _cell_formula(cell: Mapping[str, Any]) -> str:
    return str(cell.get("formula") or "")


def _norm_formula(value: str) -> str:
    return str(value or "").replace(" ", "").upper()


def _cell_matches(cell: Mapping[str, Any], expected: Any) -> bool:
    wanted = str(expected)
    if wanted.startswith("="):
        return _norm_formula(_cell_formula(cell)) == _norm_formula(wanted)
    return _cell_value(cell) == wanted


def _style_matches(cell: Mapping[str, Any], expected: Mapping[str, Any]) -> bool:
    style = cell.get("style") if isinstance(cell.get("style"), Mapping) else {}
    for field, wanted in expected.items():
        actual = style.get(field)
        if isinstance(wanted, bool) or isinstance(actual, bool):
            if bool(actual) != bool(wanted):
                return False
        elif str(actual) != str(wanted):
            return False
    return True


# Chrome saves a repeated download of "name.json" as "name (1).json", "name (2).json", ...
_COPY_SUFFIX = re.compile(r" \((\d+)\)(?=\.[^./]*$)")


def _export_order(item: Mapping[str, Any]) -> tuple[float, int, str]:
    path = str(item.get("path") or "")
    try:
        mtime = float(item.get("mtime") or 0)
    except (TypeError, ValueError):
        mtime = 0.0
    match = _COPY_SUFFIX.search(os.path.basename(path))
    return mtime, int(match.group(1)) if match else 0, path


def _newest_first(exports: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Order export files newest first: by modification time, then Chrome's "(N)" copy number."""
    unique: dict[str, dict[str, Any]] = {}
    for item in exports:
        unique.setdefault(str(item.get("path") or ""), item)
    return sorted(unique.values(), key=_export_order, reverse=True)


def _view_matches(sheet: Mapping[str, Any], expected: Mapping[str, Any]) -> bool:
    view = sheet.get("view") if isinstance(sheet.get("view"), Mapping) else {}
    for field, wanted in expected.items():
        actual = view.get(field)
        if isinstance(wanted, bool) or isinstance(actual, bool):
            if bool(actual) != bool(wanted):
                return False
        elif str(actual) != str(wanted):
            return False
    return True


class OpenSheetPlantBudgetInventoryEvaluator(BaseEvaluator):
    """Compare the stored OpenSheet workbooks with the declared final state."""

    STATE_KEY = STATE_KEY

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        controller = context.get("controller")

        checks: list[dict[str, Any]] = []

        def record(name: str, passed: bool, actual: Any) -> None:
            checks.append({"name": name, "passed": bool(passed), "actual": actual})

        key = str(params.get("state_key") or self.STATE_KEY)
        document, source = _read_document(controller, key, _directories(params))
        metadata: dict[str, Any] = {"state_key": key, "source": source, "checks": checks}
        if not isinstance(document, list):
            return EvalResult(
                status=EvalStatus.FAIL,
                message="OpenSheet workbook document is not present in Local Storage",
                metadata=metadata,
            )

        titles = [str(book.get("title") or "") for book in document if isinstance(book, Mapping)]
        metadata["workbook_titles"] = titles
        wanted_title = str(params.get("expected_workbook_title") or "")
        workbook = next(
            (book for book in document if isinstance(book, Mapping) and str(book.get("title") or "") == wanted_title),
            None,
        )
        record("workbook", workbook is not None, titles)
        if workbook is None:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="OpenSheet workbook not found: %s" % wanted_title,
                metadata=metadata,
            )

        sheets = [sheet for sheet in (workbook.get("sheets") or []) if isinstance(sheet, Mapping)]
        minimum = int(params.get("min_sheet_count") or 0)
        record("sheet_count", len(sheets) >= minimum, len(sheets))
        primary = sheets[0] if sheets else {}

        for address, expected in (params.get("expected_primary_cells") or {}).items():
            record("cell.%s" % address, _cell_matches(_cell(primary, address), expected), _cell_value(_cell(primary, address)) or _cell_formula(_cell(primary, address)))

        for address, expected in (params.get("expected_primary_notes") or {}).items():
            actual = str(_cell(primary, address).get("note") or "")
            record("note.%s" % address, actual == str(expected), actual)

        for index, spec in enumerate(params.get("expected_primary_styles") or []):
            if not isinstance(spec, Mapping):
                continue
            expected_style = spec.get("style") if isinstance(spec.get("style"), Mapping) else {}
            for address in spec.get("addresses") or []:
                record(
                    "style.%d.%s" % (index, address),
                    _style_matches(_cell(primary, str(address)), expected_style),
                    _cell(primary, str(address)).get("style"),
                )

        expected_view = params.get("expected_primary_view")
        if isinstance(expected_view, Mapping):
            record("view", _view_matches(primary, expected_view), primary.get("view"))

        expected_filters = params.get("expected_primary_filters")
        if isinstance(expected_filters, Mapping) and not expected_filters:
            record("filters", not primary.get("filters"), primary.get("filters"))

        second = sheets[1] if len(sheets) > 1 else {}
        for address, expected in (params.get("expected_second_sheet_cells") or {}).items():
            record("second.%s" % address, _cell_matches(_cell(second, address), expected), _cell_value(_cell(second, address)) or _cell_formula(_cell(second, address)))

        expected_export = params.get("expected_export")
        if isinstance(expected_export, Mapping):
            patterns = [str(item) for item in (expected_export.get("patterns") or [])]
            # The final export is the one graded ("saving the final file"): the newest matching file,
            # not the first by name ("daily-shift (1).json" sorts before "daily-shift.json").
            exports = _newest_first(self._collect_exports(controller, patterns))
            metadata["exports"] = [item.get("path") for item in exports]
            metadata["export_graded"] = exports[0].get("path") if exports else None
            record("export.file", bool(exports), [item.get("path") for item in exports])
            if exports:
                document_export = exports[0].get("document")
                # OpenSheet JSON export writes the current workbook object; a list of workbooks is also accepted.
                if isinstance(document_export, Mapping):
                    books = [document_export]
                else:
                    books = document_export if isinstance(document_export, list) else []
                export_title = str(expected_export.get("expected_title") or "")
                export_book = next(
                    (book for book in books if isinstance(book, Mapping) and str(book.get("title") or "") == export_title),
                    None,
                )
                record("export.workbook", export_book is not None, [str(book.get("title") or "") for book in books if isinstance(book, Mapping)])
                if export_book is not None:
                    export_sheets = [sheet for sheet in (export_book.get("sheets") or []) if isinstance(sheet, Mapping)]
                    record("export.sheet_count", len(export_sheets) >= int(expected_export.get("min_sheet_count") or 0), len(export_sheets))
                    export_primary = export_sheets[0] if export_sheets else {}
                    for address, expected in (expected_export.get("expected_primary_cells") or {}).items():
                        record("export.cell.%s" % address, _cell_matches(_cell(export_primary, address), expected), _cell_value(_cell(export_primary, address)) or _cell_formula(_cell(export_primary, address)))
                    export_second = export_sheets[1] if len(export_sheets) > 1 else {}
                    for address, expected in (expected_export.get("expected_second_sheet_cells") or {}).items():
                        record("export.second.%s" % address, _cell_matches(_cell(export_second, address), expected), _cell_value(_cell(export_second, address)) or _cell_formula(_cell(export_second, address)))

        failures = [item["name"] for item in checks if not item["passed"]]
        if failures:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="OpenSheet final state does not match: %s" % ", ".join(failures[:8]),
                metadata=metadata,
            )
        return EvalResult(
            status=EvalStatus.PASS,
            message="OpenSheet final state matches the declared state",
            metadata=metadata,
        )

    @staticmethod
    def _collect_exports(controller: Any, patterns: list[str]) -> list[dict[str, Any]]:
        program = (
            "import glob, json, os\n"
            "patterns = json.loads(%s)\n"
            "found = []\n"
            "for pattern in patterns:\n"
            "    for path in sorted(glob.glob(pattern)):\n"
            "        document = None\n"
            "        try:\n"
            "            with open(path, encoding='utf-8') as handle:\n"
            "                document = json.load(handle)\n"
            "        except Exception:\n"
            "            document = None\n"
            "        try:\n"
            "            mtime = os.path.getmtime(path)\n"
            "        except OSError:\n"
            "            mtime = 0\n"
            "        found.append({'path': path, 'mtime': mtime, 'document': document})\n"
            "print(json.dumps(found, ensure_ascii=False))\n"
        ) % json.dumps(json.dumps(patterns))
        parsed = _run_python(controller, program, timeout=60)
        if isinstance(parsed, list):
            return [dict(item) for item in parsed if isinstance(item, Mapping)]
        found: list[dict[str, Any]] = []
        for pattern in patterns:
            for path in sorted(glob.glob(pattern)):
                document = None
                try:
                    with open(path, encoding="utf-8") as handle:
                        document = json.load(handle)
                except Exception:
                    document = None
                try:
                    mtime = os.path.getmtime(path)
                except OSError:
                    mtime = 0
                found.append({"path": path, "mtime": mtime, "document": document})
        return found
